  var levels=new List<List<SKColor[]>>();int w=width,h=height,d=depth;
  while(true){levels.Add(pixels);if(w==1&&h==1&&(!volume||d==1))break;int nw=Math.Max(1,w/2),nh=Math.Max(1,h/2),nd=volume?Math.Max(1,d/2):d;var next=new List<SKColor[]>();
   for(int z=0;z<nd;z++)for(int f=0;f<faces;f++){var dst=new SKColor[nw*nh];for(int y=0;y<nh;y++)for(int x=0;x<nw;x++){int r=0,g=0,b=0,a=0,n=0;for(int dz=0;dz<(volume?2:1);dz++)for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){var c=pixels[Math.Min(d-1,volume?z*2+dz:z)*faces+f][Math.Min(h-1,y*2+dy)*w+Math.Min(w-1,x*2+dx)];r+=c.Red;g+=c.Green;b+=c.Blue;a+=c.Alpha;n++;}dst[y*nw+x]=new SKColor((byte)(r/n),(byte)(g/n),(byte)(b/n),(byte)(a/n));}next.Add(dst);}pixels=next;w=nw;h=nh;d=nd;}
  var extras=texture.ExtraData.Where(p=>p.Key.ToString()!="COMPRESSED_MIP_SIZE").Select(p=>(Type:(uint)p.Key,Data:p.Value.ToArray(),Name:p.Key.ToString())).ToArray();
