  int dataSize=40+extras.Length*12+extras.Sum(e=>e.Data.Length);using var stream=File.Create(output);using var writer=new BinaryWriter(stream);writer.Write((uint)(28+dataSize));writer.Write((ushort)12);writer.Write((ushort)1);writer.Write(8u);writer.Write(1u);writer.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));writer.Write(8u);writer.Write((uint)dataSize);writer.Write((ushort)1);writer.Write((ushort)texture.Flags);writer.Write(texture.Reflectivity.X);writer.Write(texture.Reflectivity.Y);writer.Write(texture.Reflectivity.Z);writer.Write(texture.Reflectivity.W);writer.Write((ushort)width);writer.Write((ushort)height);writer.Write((ushort)depth);writer.Write((byte)4);writer.Write((byte)levels.Count);writer.Write(0u);writer.Write(extras.Length>0?8u:0u);writer.Write((uint)extras.Length);
  int offset=40+extras.Length*12;for(int i=0;i<extras.Length;i++){writer.Write(extras[i].Type);writer.Write((uint)(offset-(40+i*12+4)));writer.Write((uint)extras[i].Data.Length);offset+=extras[i].Data.Length;}foreach(var e in extras)writer.Write(e.Data);
