 }
 private static bool SamePixels(SKBitmap a,SKBitmap b,bool color){if(a.Width!=b.Width||a.Height!=b.Height)return false;bool Equal(SKColor[] aa,SKColor[] bb,bool visibleOnly){for(int i=0;i<aa.Length;i++)if(aa[i].Alpha!=bb[i].Alpha||((!visibleOnly||aa[i].Alpha!=0)&&aa[i]!=bb[i]))return false;return true;}var pixels=a.Pixels;if(Equal(pixels,b.Pixels,false))return true;if(!color)return false;if(Equal(pixels,b.Pixels,true))return true;using var image=SKImage.FromBitmap(b);using var png=image.Encode(SKEncodedImageFormat.Png,100);using var roundtrip=SKBitmap.Decode(png.ToArray());return roundtrip is not null&&Equal(pixels,roundtrip.Pixels,true);}

 public static void Run(string manifest){
  var request=JsonSerializer.Deserialize<Request>(File.ReadAllText(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidDataException("Empty texture request");using var r=new Resource{FileName=request.Input};r.Read(request.Input);if(r.DataBlock is not Texture texture)throw new InvalidDataException("Expected compiled texture");int faces=Faces(texture);if(request.Layer<0||request.Layer>=texture.Depth||request.Face<0||request.Face>=faces)throw new InvalidDataException("Invalid texture layer/face");using var original=texture.GenerateBitmap((uint)request.Layer,(Texture.CubemapFace)request.Face);
